import { addDays, differenceInCalendarDays, format, parseISO } from 'date-fns'

/**
 * Dua Streak — a day counts only when both partners showed up.
 *
 * The whole design constraint: this must never become a stick to beat someone
 * with. So the engine has rest days, pause, and a repair window, and it exposes
 * lifetime totals alongside the current run — losing a streak must not erase
 * years of history.
 *
 * Explicitly impossible by construction:
 *   - completing on a partner's behalf
 *   - buying a streak back
 *   - one person doing two things to count as two people
 */

/** What a partner did that day. Any one of these is enough. */
export type ContributionKind =
  | 'connect'
  | 'appreciate'
  | 'coordinate'
  | 'care'
  | 'household'
  | 'reflect'
  | 'plan'
  | 'repair'
  | 'play'
  | 'memory'

export interface DayRecord {
  /** yyyy-MM-dd in the couple's chosen day window. */
  date: string
  a?: ContributionKind
  b?: ContributionKind
  /** Deliberate day off. Counts as unbroken, earns nothing. */
  rest?: boolean
  /** Illness, travel, bereavement. Neither counts nor breaks. */
  paused?: boolean
  /** A missed day the pair later closed together. */
  repaired?: boolean
}

export interface StreakConfig {
  /** Hour the day flips. Shift workers and LDR pairs need this to not be midnight. */
  dayStartHour: number
  /** Rest days granted per calendar month. */
  restPerMonth: number
  /** Hours after a missed day in which it can still be repaired together. */
  repairWindowHours: number
}

export const DEFAULT_CONFIG: StreakConfig = {
  dayStartHour: 4,
  restPerMonth: 2,
  repairWindowHours: 72,
}

export interface StreakState {
  /** Consecutive unbroken days, counting rest, pause, and repaired days. */
  current: number
  longest: number
  /** Days both partners actually showed up. This is what grows Temu. */
  pairDays: number
  restUsed: number
  repairsUsed: number
  pausedDays: number
  /** Of the days since pairing, the share that were complete. Never shown as a grade. */
  consistency: number
  /** Today's two halves. */
  today: { a: boolean; b: boolean; complete: boolean }
  /** A missed day still inside the repair window, if any. */
  repairable: string | null
}

/** The date a moment belongs to, honouring the couple's day-start hour. */
export function dayKeyFor(at: Date, config: StreakConfig = DEFAULT_CONFIG): string {
  const shifted = new Date(at)
  if (shifted.getHours() < config.dayStartHour) shifted.setDate(shifted.getDate() - 1)
  return format(shifted, 'yyyy-MM-dd')
}

function isComplete(d: DayRecord): boolean {
  return Boolean(d.a && d.b)
}

/** Unbroken means complete, resting, paused, or repaired — not merely present. */
function isUnbroken(d: DayRecord | undefined): boolean {
  if (!d) return false
  return isComplete(d) || Boolean(d.rest) || Boolean(d.paused) || Boolean(d.repaired)
}

export function computeStreak(
  records: DayRecord[],
  now: Date,
  config: StreakConfig = DEFAULT_CONFIG,
): StreakState {
  const byDate = new Map(records.map((r) => [r.date, r]))
  const todayKey = dayKeyFor(now, config)
  const today = byDate.get(todayKey)

  // Walk backwards from today. Today being incomplete does not break the run —
  // there is still time left in it.
  let current = 0
  let cursor = todayKey
  if (isUnbroken(today)) {
    current = 1
    cursor = format(addDays(parseISO(todayKey), -1), 'yyyy-MM-dd')
  } else {
    cursor = format(addDays(parseISO(todayKey), -1), 'yyyy-MM-dd')
  }
  while (isUnbroken(byDate.get(cursor))) {
    current++
    cursor = format(addDays(parseISO(cursor), -1), 'yyyy-MM-dd')
  }

  // Longest run in the whole history.
  const sorted = [...records].sort((x, y) => x.date.localeCompare(y.date))
  let longest = 0
  let run = 0
  let prev: string | null = null
  for (const r of sorted) {
    if (!isUnbroken(r)) {
      run = 0
      prev = r.date
      continue
    }
    run = prev && differenceInCalendarDays(parseISO(r.date), parseISO(prev)) === 1 ? run + 1 : 1
    longest = Math.max(longest, run)
    prev = r.date
  }
  longest = Math.max(longest, current)

  const pairDays = records.filter(isComplete).length
  const month = todayKey.slice(0, 7)
  const restUsed = records.filter((r) => r.rest && r.date.startsWith(month)).length
  const eligible = records.filter((r) => !r.paused).length

  return {
    current,
    longest,
    pairDays,
    restUsed,
    repairsUsed: records.filter((r) => r.repaired).length,
    pausedDays: records.filter((r) => r.paused).length,
    consistency: eligible === 0 ? 0 : records.filter(isComplete).length / eligible,
    today: { a: Boolean(today?.a), b: Boolean(today?.b), complete: isComplete(today ?? { date: todayKey }) },
    repairable: findRepairable(byDate, todayKey, config),
  }
}

/**
 * The most recent broken day still inside the repair window.
 * Only one at a time — repair is a small kindness, not a way to rebuild a month.
 */
function findRepairable(
  byDate: Map<string, DayRecord>,
  todayKey: string,
  config: StreakConfig,
): string | null {
  // Nothing to repair before the pair has ever completed a day — offering it on
  // day zero reads as "you already failed", which is the opposite of the point.
  if (byDate.size === 0) return null
  const days = Math.floor(config.repairWindowHours / 24)
  for (let i = 1; i <= days; i++) {
    const key = format(addDays(parseISO(todayKey), -i), 'yyyy-MM-dd')
    const rec = byDate.get(key)
    if (!isUnbroken(rec)) return key
  }
  return null
}

export function restRemaining(state: StreakState, config: StreakConfig = DEFAULT_CONFIG): number {
  return Math.max(0, config.restPerMonth - state.restUsed)
}

/**
 * Nadi earned for a completed day. Flat — a longer streak must not make a
 * missed day more expensive, or the streak becomes a debt.
 */
export const NADI_PER_PAIR_DAY = 10

export const NADI_REWARDS = {
  pairDay: NADI_PER_PAIR_DAY,
  weeklyQuest: 25,
  monthlyReflection: 50,
  repair: 15,
  moneyMeeting: 20,
  qualityTime: 20,
} as const

/**
 * Which milestones a pair-day count has just crossed. Used to fire the one big
 * celebration animation, and nothing else.
 */
export const MILESTONES = [7, 30, 100, 180, 365, 550, 730, 1095, 1825, 2555, 3650] as const

export function milestoneReached(before: number, after: number): number | null {
  for (const m of MILESTONES) {
    if (before < m && after >= m) return m
  }
  return null
}
