import { growth as computeGrowth, PALETTES, shapeFor, type Growth, type Lineage } from './model'

/**
 * Sharing Temu — renders a card to PNG in the browser and hands it to the
 * native share sheet, falling back to a download.
 *
 * Deliberately no html2canvas: the character is already SVG, so it can be
 * serialised, drawn to a canvas, and exported with zero dependencies.
 *
 * The card carries a name, a stage, and two day counts — never a per-partner
 * breakdown. There is nothing here that could be screenshotted and used to
 * make a point about who did more.
 */

const W = 1080
const H = 1350

export interface ShareInput {
  growth: Growth
  lineage: Lineage
  name: string
  pairDays: number
  streak: number
  caption: string
}

export async function shareTemu(input: ShareInput): Promise<boolean> {
  const blob = await renderCard(input)
  if (!blob) return false

  const file = new File([blob], `temu-${input.pairDays}hari.png`, { type: 'image/png' })

  // Native sheet when available — on Android this is the whole point.
  if (navigator.canShare?.({ files: [file] })) {
    try {
      await navigator.share({ files: [file], text: input.caption })
      return true
    } catch {
      // User dismissed the sheet. Not an error, and not worth a fallback.
      return false
    }
  }

  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = file.name
  a.style.display = 'none'
  document.body.appendChild(a)
  a.click()
  a.remove()
  setTimeout(() => URL.revokeObjectURL(url), 0)
  return true
}

async function renderCard(input: ShareInput): Promise<Blob | null> {
  const canvas = document.createElement('canvas')
  canvas.width = W
  canvas.height = H
  const ctx = canvas.getContext('2d')
  if (!ctx) return null

  const p = PALETTES[input.lineage]

  const bg = ctx.createLinearGradient(0, 0, W * 0.4, H)
  bg.addColorStop(0, p.highlight)
  bg.addColorStop(0.55, mix(p.highlight, '#FFFFFF', 0.5))
  bg.addColorStop(1, '#FFFFFF')
  ctx.fillStyle = bg
  ctx.fillRect(0, 0, W, H)

  // A soft aura behind the character, matching the in-app stage.
  const glow = ctx.createRadialGradient(W / 2, H * 0.42, 40, W / 2, H * 0.42, W * 0.5)
  glow.addColorStop(0, hexA(p.body, 0.3))
  glow.addColorStop(1, hexA(p.body, 0))
  ctx.fillStyle = glow
  ctx.fillRect(0, 0, W, H)

  const svg = await rasterise(input)
  if (svg) {
    const size = W * 0.62
    ctx.drawImage(svg, (W - size) / 2, H * 0.42 - size / 2, size, size)
  }

  ctx.textAlign = 'center'
  ctx.fillStyle = '#293145'

  ctx.font = '800 76px Nunito, system-ui, sans-serif'
  ctx.fillText(input.name, W / 2, H * 0.68)

  ctx.font = '700 40px Nunito, system-ui, sans-serif'
  ctx.fillStyle = hexA('#293145', 0.62)
  ctx.fillText(input.caption, W / 2, H * 0.73)

  // Two counts, both about the pair.
  drawPill(ctx, W / 2 - 220, H * 0.79, 200, 92, p.body, String(input.pairDays), 'hari berdua')
  drawPill(ctx, W / 2 + 20, H * 0.79, 200, 92, p.deep, String(input.streak), 'berturut-turut')

  ctx.font = '700 30px Nunito, system-ui, sans-serif'
  ctx.fillStyle = hexA('#293145', 0.4)
  ctx.fillText('TemuDua', W / 2, H * 0.93)

  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'))
}

function drawPill(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  colour: string,
  big: string,
  small: string,
) {
  ctx.fillStyle = hexA(colour, 0.16)
  ctx.beginPath()
  ctx.roundRect(x, y, w, h, 28)
  ctx.fill()

  ctx.fillStyle = '#293145'
  ctx.font = '800 44px Nunito, system-ui, sans-serif'
  ctx.fillText(big, x + w / 2, y + 48)
  ctx.font = '700 22px Nunito, system-ui, sans-serif'
  ctx.fillStyle = hexA('#293145', 0.55)
  ctx.fillText(small, x + w / 2, y + 78)
}

/**
 * Draws the character to an image without a DOM node.
 *
 * The rendered SVG uses `var(--ink)` for the face, which does not resolve
 * inside a detached image — so the markup is generated here with literal
 * colours instead of reusing the React component.
 */
function rasterise(input: ShareInput): Promise<HTMLImageElement | null> {
  const p = PALETTES[input.lineage]
  const s = shapeFor(input.growth)
  const cx = 100
  const groundY = 172
  const bottom = groundY - s.leg
  const top = bottom - s.bodyH
  const w = s.bodyH * s.bodyW
  const faceCy = top + s.bodyH * s.faceY
  const eyeR = Math.max(1.6, s.bodyH * 0.055)
  const eyeDx = w * 0.15
  const crestBase = top + s.bodyH * 0.06
  const crestTip = crestBase - s.crest
  const crossY = crestBase - s.crest * 0.4
  const sp = Math.max(s.crestSpread, 1)
  const cw = Math.max(1.8, s.crest * 0.16)

  const markup = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="600" height="600">
<defs>
<linearGradient id="b" x1="18%" y1="0%" x2="82%" y2="100%">
<stop offset="0%" stop-color="${p.highlight}"/><stop offset="55%" stop-color="${p.body}"/><stop offset="100%" stop-color="${p.deep}"/>
</linearGradient>
<linearGradient id="c" x1="0%" y1="100%" x2="100%" y2="0%">
<stop offset="0%" stop-color="${p.body}"/><stop offset="100%" stop-color="${p.highlight}"/>
</linearGradient>
</defs>
<ellipse cx="${cx}" cy="${groundY + 5}" rx="${w * 0.36}" ry="${s.bodyH * 0.05}" fill="#293145" opacity="0.1"/>
<g transform="rotate(${s.lean} ${cx} ${groundY})">
${s.leg > 0 ? `<g stroke="${p.deep}" stroke-width="${Math.max(2.6, s.leg * 0.3)}" stroke-linecap="round">
<line x1="${cx - w * 0.17}" y1="${bottom}" x2="${cx - w * 0.19}" y2="${bottom + s.leg}"/>
<line x1="${cx + w * 0.17}" y1="${bottom}" x2="${cx + w * 0.19}" y2="${bottom + s.leg}"/></g>` : ''}
${s.crest > 0 ? `<g fill="none" stroke="url(#c)" stroke-width="${cw}" stroke-linecap="round">
<path d="M ${cx - sp * 0.5} ${crestBase} Q ${cx - sp * 0.9} ${crossY}, ${cx + sp * 0.75} ${crestTip}"/>
<path d="M ${cx + sp * 0.5} ${crestBase} Q ${cx + sp * 0.9} ${crossY}, ${cx - sp * 0.75} ${crestTip}"/></g>` : ''}
<path d="${bean(cx, top, w, s.bodyH)}" fill="url(#b)"/>
${s.arm > 0 ? `<g fill="none" stroke="${p.deep}" stroke-width="${Math.max(2.4, s.arm * 0.17)}" stroke-linecap="round">
<path d="M ${cx - w * 0.44} ${top + s.bodyH * 0.56} q ${-s.arm * 0.55} ${s.arm * 0.1}, ${-s.arm * 0.8} ${s.arm * 0.42}"/>
<path d="M ${cx + w * 0.44} ${top + s.bodyH * 0.56} q ${s.arm * 0.55} ${s.arm * 0.1}, ${s.arm * 0.8} ${s.arm * 0.42}"/></g>` : ''}
<ellipse cx="${cx}" cy="${faceCy}" rx="${w * 0.26}" ry="${s.bodyH * 0.21}" fill="${p.face}" opacity="0.92"/>
<path d="M ${cx - eyeDx - eyeR} ${faceCy - s.bodyH * 0.03 + eyeR * 0.3} q ${eyeR} ${-eyeR * 1.25}, ${eyeR * 2} 0" fill="none" stroke="#293145" stroke-width="${eyeR * 0.62}" stroke-linecap="round"/>
<path d="M ${cx + eyeDx - eyeR} ${faceCy - s.bodyH * 0.03 + eyeR * 0.3} q ${eyeR} ${-eyeR * 1.25}, ${eyeR * 2} 0" fill="none" stroke="#293145" stroke-width="${eyeR * 0.62}" stroke-linecap="round"/>
<ellipse cx="${cx}" cy="${faceCy + s.bodyH * 0.09}" rx="${s.bodyH * 0.034}" ry="${s.bodyH * 0.04}" fill="#293145"/>
<ellipse cx="${cx - eyeDx * 1.55}" cy="${faceCy + s.bodyH * 0.02}" rx="${eyeR * 1.5}" ry="${eyeR}" fill="${p.accent}" opacity="0.5"/>
<ellipse cx="${cx + eyeDx * 1.55}" cy="${faceCy + s.bodyH * 0.02}" rx="${eyeR * 1.5}" ry="${eyeR}" fill="${p.accent}" opacity="0.5"/>
</g></svg>`

  return new Promise((resolve) => {
    const img = new Image()
    img.onload = () => resolve(img)
    img.onerror = () => resolve(null)
    img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(markup)}`
  })
}

function bean(cx: number, top: number, w: number, h: number): string {
  const hw = w / 2
  const l = cx - hw
  const r = cx + hw
  const b = top + h
  return `M ${cx} ${top} C ${cx + hw * 0.72} ${top}, ${r} ${top + h * 0.2}, ${r} ${top + h * 0.5} C ${r} ${top + h * 0.82}, ${cx + hw * 0.66} ${b}, ${cx} ${b} C ${cx - hw * 0.62} ${b}, ${l} ${top + h * 0.84}, ${l} ${top + h * 0.52} C ${l} ${top + h * 0.22}, ${cx - hw * 0.68} ${top}, ${cx} ${top} Z`
}

function hexA(hex: string, alpha: number): string {
  const n = parseInt(hex.slice(1), 16)
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`
}

function mix(a: string, b: string, t: number): string {
  const pa = parseInt(a.slice(1), 16)
  const pb = parseInt(b.slice(1), 16)
  const ch = (shift: number) =>
    Math.round((((pa >> shift) & 255) * (1 - t) + ((pb >> shift) & 255) * t))
  return `rgb(${ch(16)}, ${ch(8)}, ${ch(0)})`
}

export { computeGrowth }
